create table public.journal_entries (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete restrict, title text not null check(length(title) between 1 and 160), body text not null check(length(body) between 1 and 10000), visibility text not null default 'private' check(visibility in ('private','shared')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.journal_revisions (id uuid primary key default gen_random_uuid(), entry_id uuid not null references public.journal_entries(id) on delete cascade, revision_no int not null, title text not null, body text not null, actor_id uuid not null references public.profiles(id), created_at timestamptz not null default now(), unique(entry_id,revision_no));
alter table public.journal_entries enable row level security; alter table public.journal_revisions enable row level security;
revoke all on public.journal_entries,public.journal_revisions from anon,authenticated;
grant select,insert,update on public.journal_entries to authenticated; grant select on public.journal_revisions to authenticated;
create policy journal_own on public.journal_entries for all to authenticated using(student_id=(select auth.uid())) with check(student_id=(select auth.uid()));
create policy journal_revision_own on public.journal_revisions for select to authenticated using(exists(select 1 from public.journal_entries e where e.id=entry_id and e.student_id=(select auth.uid())));
create or replace function public.create_journal_entry(p_title text,p_body text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare entry_id uuid; begin if auth.uid() is null then raise exception 'unauthenticated'; end if; insert into public.journal_entries(student_id,title,body) values(auth.uid(),p_title,p_body) returning id into entry_id; insert into public.journal_revisions(entry_id,revision_no,title,body,actor_id) values(entry_id,1,p_title,p_body,auth.uid()); return entry_id; end $$;
revoke all on function public.create_journal_entry(text,text) from public; grant execute on function public.create_journal_entry(text,text) to authenticated;
create or replace function public.revise_journal_entry(p_entry_id uuid,p_title text,p_body text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare e public.journal_entries; n int; begin select * into e from public.journal_entries where id=p_entry_id and student_id=auth.uid() for update; if e.id is null then raise exception 'journal not found'; end if; select coalesce(max(revision_no),0)+1 into n from public.journal_revisions where entry_id=e.id; update public.journal_entries set title=p_title,body=p_body,updated_at=now() where id=e.id; insert into public.journal_revisions(entry_id,revision_no,title,body,actor_id) values(e.id,n,p_title,p_body,auth.uid()); return e.id; end $$;
revoke all on function public.revise_journal_entry(uuid,text,text) from public; grant execute on function public.revise_journal_entry(uuid,text,text) to authenticated;
